node -e 'try {
  const fs = require("node:fs");
  const { spawn } = require("node:child_process");
  const input = JSON.parse(fs.readFileSync(0, "utf8"));
  if (input.reason === "resume") process.exit(0);
  if (!input.transcript_path) process.exit(0);
  const messages = [];
  for (const line of fs.readFileSync(input.transcript_path, "utf8").trim().split("\n")) {
    try {
      const entry = JSON.parse(line);
      if (entry.type !== "assistant") continue;
      const content = entry.message.content;
      if (typeof content === "string") messages.push(content);
      else if (Array.isArray(content)) {
        messages.push(content.filter(block => block?.type === "text").map(block => block.text).join(" "));
      }
    } catch { /* Skip malformed transcript records. */ }
  }
  const summary = Array.from(messages.join("\n")).slice(-1500).join("").replace(/\n/g, " ");
  if (summary.length < 20) process.exit(0);
  const env = { ...process.env,
    ENGRAM_DB_PATH: process.env.ENGRAM_DB_PATH || "~/.engram/engram.db",
    ENGRAM_SOURCE: process.env.ENGRAM_SOURCE || "claude-code"
  };
  const args = ["-y", "-p", "@engram-ai-memory/mcp@latest", "engram-store-session"];
  const reportLaunchError = err => console.error("[engram] Could not launch engram-store-session:", err.code || err.name);
  try {
    let command = "npx";
    if (process.platform === "win32") {
      const path = require("node:path");
      command = process.execPath;
      args.unshift(require.resolve(path.join(path.dirname(command), "node_modules", "npm", "bin", "npx-cli.js")));
    }
    const child = spawn(command, args, { detached: true, stdio: ["pipe", "ignore", "ignore"], env });
    child.once("error", reportLaunchError);
    child.stdin.once("error", reportLaunchError);
    child.stdin.end("Session summary: " + summary);
    child.unref();
  } catch (err) { reportLaunchError(err); }
} catch {}' >/dev/null || true

node -e 'try {
  const input = JSON.parse(require("node:fs").readFileSync(0, "utf8"));
  const file = input.tool_input?.file_path;
  const path = require("node:path");
  if (typeof file !== "string" || !path.isAbsolute(file) || path.basename(file) === "MEMORY.md") process.exit(0);
  const normalized = path.normalize(file).split(path.sep).join("/");
  if (!/\/\.claude\/projects\/[^/]+\/memory\/[^/]*\.md$/.test(normalized)) process.exit(0);
  const args = ["-y", "-p", "@engram-ai-memory/mcp@latest", "engram-store-memory-file"];
  let command = "npx";
  if (process.platform === "win32") {
    command = process.execPath;
    args.unshift(require.resolve(path.join(path.dirname(command), "node_modules", "npm", "bin", "npx-cli.js")));
  }
  const child = require("node:child_process").spawn(command, args, {
    cwd: input.cwd || process.cwd(), detached: true, stdio: ["pipe", "ignore", "ignore"]
  });
  const report = err => console.error("[engram] Could not launch memory mirror:", err.message);
  child.once("error", report);
  child.stdin.once("error", report);
  child.stdin.end(file);
  child.unref();
} catch (err) { console.error("[engram] Could not mirror memory file:", err.message); }' >/dev/null || true
